const tech = (x: Omit<TechnologyInput, "kind" | "asOf">): TechnologyInput => ({ kind: "technology", asOf, ...x });
/** An approach, with its honest grade. */
const T = (grade: EvidenceGrade, extra: string[] = []) => ["rejuvenation", "survivorship", "transplant", `evidence:${grade}`, ...extra];
/** A complication or a measurement: described, not recommended, so no grade. */
const C = (extra: string[] = []) => ["rejuvenation", "survivorship", "transplant", ...extra];

